SELECT ?label ?labelLabelEn ?labelLabelRu ?genre ?genreLabelEn ?genreLabelRu ?period_start ?gold_count_estimate WHERE {
      {
        SELECT ?label ?labelLabelEn ?labelLabelRu ?genre ?genreLabelEn ?genreLabelRu ?period_start (COUNT(DISTINCT ?item) AS ?gold_count_estimate) WHERE {
        {
          ?item wdt:P31 wd:Q215380 .
        } UNION {
          ?item wdt:P106 wd:Q639669 .
        }
        ?release wdt:P31 wd:Q169930 .
        ?release wdt:P175 ?item .
        ?release wdt:P577 ?date .
        BIND(YEAR(?date) AS ?year) .
        FILTER(?year >= 1950 && ?year <= 2025) .
        ?release wdt:P264 ?label .
        ?release wdt:P136 ?genre .
        ?label rdfs:label ?labelLabelEn FILTER(LANG(?labelLabelEn) = "en") .
        OPTIONAL { ?label rdfs:label ?labelLabelRu FILTER(LANG(?labelLabelRu) = "ru") . }
        ?genre rdfs:label ?genreLabelEn FILTER(LANG(?genreLabelEn) = "en") .
        OPTIONAL { ?genre rdfs:label ?genreLabelRu FILTER(LANG(?genreLabelRu) = "ru") . }
        BIND((FLOOR((?year - 1950) / 10) * 10 + 1950) AS ?period_start) .
        }
        GROUP BY ?label ?labelLabelEn ?labelLabelRu ?genre ?genreLabelEn ?genreLabelRu ?period_start
      }
      FILTER(?gold_count_estimate >= 5 && ?gold_count_estimate <= 180)
    }
    ORDER BY DESC(?gold_count_estimate)
    LIMIT 800

